// Run Agents settings. lockMinutes: a run lock older than this is treated as abandoned.
// promptVersion must match the header of build_prompt.js; a run row with another prompt_version is refused.
return [{ json: { lockMinutes: 30, promptVersion: 'mm-v1' } }];

// Pick the run this execution works on: a running run first, else the oldest queued one.
// Output: one item with the lock update body for the runs table (locked_at + locked_by = this execution),
// plus the run itself under `run` (ignored by the Baserow node via Inputs to Ignore). No item when
// there is nothing to do.
const config = $('Configuration').first().json;
const runs = $input.all().map((i) => i.json).filter((r) => r && r.run_id);
const byAge = (a, b) => String(a.started_at || '').localeCompare(String(b.started_at || '')) || a.id - b.id;
const running = runs.filter((r) => r.status === 'running').sort(byAge);
const queued = runs.filter((r) => r.status === 'queued').sort((a, b) => a.id - b.id);
const run = running[0] || queued[0];
if (!run) return [];

const now = new Date();
const lockMs = (Number(config.lockMinutes) || 30) * 60 * 1000;
if (run.locked_at && now.getTime() - Date.parse(run.locked_at) < lockMs) {
  // Another execution is still working on this run; leave it alone.
  return [];
}

const provider = String(run.provider || '').trim().toLowerCase();
if (!['ollama', 'bedrock'].includes(provider)) throw new Error(`run ${run.run_id}: provider must be ollama or bedrock, got "${run.provider}"`);
if (!String(run.model || '').trim()) throw new Error(`run ${run.run_id}: model is required`);
if (run.prompt_version && run.prompt_version !== config.promptVersion) {
  throw new Error(`run ${run.run_id}: prompt_version "${run.prompt_version}" does not match this workflow's prompt "${config.promptVersion}"`);
}
const batchSize = Math.max(1, Math.floor(Number(run.batch_size) || 25));
const temperature = run.temperature === '' || run.temperature === null || run.temperature === undefined ? null : Number(run.temperature);

const iso = now.toISOString().replace(/\.\d{3}Z$/, '+00:00');
return [{
  json: {
    run: { ...run, provider, model: String(run.model).trim(), batch_size: batchSize, temperature, prompt_version: config.promptVersion },
    status: 'running',
    locked_at: iso,
    locked_by: $execution.id,
    started_at: run.started_at || iso,
    prompt_version: config.promptVersion,
    batch_size: batchSize,
  },
}];

// Decide which participants this execution asks. Input: every agent_turns row (Read: agent_turns).
// Output: up to batch_size items, one per participant still unanswered for the picked run,
// or a single { noWork: true } item when the run has nobody left.
const run = $('Pick run').first().json.run;
const participants = $('Read: participants').all().map((i) => i.json);
const turns = $input.all().map((i) => i.json).filter((t) => t && t.run_id === run.run_id);
const answered = new Set(turns.map((t) => String(t.participant_id)));

const todo = participants
  .filter((p) => p && p.persona && !answered.has(String(p.participant_id)))
  .sort((a, b) => Number(a.participant_id) - Number(b.participant_id));

if (todo.length === 0) return [{ json: { noWork: true, remaining: 0, run_id: run.run_id } }];

return todo.slice(0, run.batch_size).map((p) => ({
  json: {
    noWork: false,
    remaining: todo.length,
    run_id: run.run_id,
    provider: run.provider,
    model: run.model,
    temperature: run.temperature,
    prompt_version: run.prompt_version,
    participant_id: Number(p.participant_id),
    persona: p.persona,
  },
}));

// Prompt version mm-v1. The 40 Saucier Mini-Marker adjectives in tda1..tda40 order; this list must
// match the ADJECTIVES list in normalize_humans.js (code_nodes.test.mjs checks it).
const ADJECTIVES = ['Bashful', 'Bold', 'Careless', 'Cold', 'Complex', 'Cooperative', 'Creative', 'Deep', 'Disorganized', 'Efficient',
  'Energetic', 'Envious', 'Extraverted', 'Fretful', 'Harsh', 'Imaginative', 'Inefficient', 'Intellectual', 'Jealous', 'Kind',
  'Moody', 'Organized', 'Philosophical', 'Practical', 'Quiet', 'Relaxed', 'Rude', 'Shy', 'Sloppy', 'Sympathetic',
  'Systematic', 'Talkative', 'Temperamental', 'Touchy', 'Uncreative', 'Unenvious', 'Unintellectual', 'Unsympathetic', 'Warm', 'Withdrawn'];

const item = $input.first().json;
const list = ADJECTIVES.map((a, i) => `${i + 1}. ${a}: <score>`).join('\n');
const prompt = `You are answering a personality questionnaire as the person described below. Stay in character and answer about yourself as that person would.

About you. These are your own answers to a personality questionnaire, where 1 = disagree strongly and 5 = agree strongly:
${item.persona}

Rate how accurately each of the following adjectives describes you, as that person, using this scale:
1 = Extremely inaccurate
2 = Very inaccurate
3 = Moderately inaccurate
4 = Slightly inaccurate
5 = Neither accurate nor inaccurate
6 = Slightly accurate
7 = Moderately accurate
8 = Very accurate
9 = Extremely accurate

Reply with exactly 40 lines, one per adjective, in this order and format, and nothing else:
${list}`;

return [{ json: { ...item, prompt, adjectives: ADJECTIVES, startedAt: Date.now() } }];

// Turn the model's reply into one agent_turns row: the bookkeeping columns plus tda1..tda40 when the
// reply parsed cleanly. ok is true only when every adjective appears exactly once with an integer 1-9.
const ctx = $('Build prompt').first().json;
const reply = $input.first().json || {};
const text = typeof reply.text === 'string' ? reply.text : typeof reply.output === 'string' ? reply.output : '';
const now = new Date();
const iso = now.toISOString().replace(/\.\d{3}Z$/, '+00:00');

const byAdjective = new Map(ctx.adjectives.map((a, i) => [a.toLowerCase(), { item_key: `tda${i + 1}`, text: a }]));
const found = new Map();
const problems = [];

if (!text) {
  problems.push(`llm: ${reply.error || 'empty reply'}`);
} else {
  const linePattern = /^\s*(?:[-*•]\s*)?(?:\d{1,2}\s*[.)]\s*)?[*_]*([A-Za-z][A-Za-z\- ]*?)[*_]*\s*(?:[:\-–—]|\s)\s*[*_]*(\d{1,2})[*_]*\s*[.)]?\s*$/;
  for (const raw of text.split(/\r?\n/)) {
    const m = raw.match(linePattern);
    if (!m) continue;
    const entry = byAdjective.get(m[1].trim().toLowerCase());
    if (!entry) continue;
    const value = Number(m[2]);
    if (found.has(entry.item_key)) {
      problems.push(`duplicate: ${entry.text}`);
      continue;
    }
    if (!Number.isInteger(value) || value < 1 || value > 9) {
      problems.push(`out of range: ${entry.text} = ${value}`);
      continue;
    }
    found.set(entry.item_key, value);
  }
  const missing = ctx.adjectives.filter((a) => !found.has(byAdjective.get(a.toLowerCase()).item_key));
  if (missing.length) problems.push(`missing: ${missing.join(', ')}`);
}

const ok = problems.length === 0 && found.size === ctx.adjectives.length;
const values = ok ? Object.fromEntries(found) : {};

return [{
  json: {
    key: `${ctx.run_id}:${ctx.participant_id}`,
    run_id: ctx.run_id,
    participant_id: ctx.participant_id,
    provider: ctx.provider,
    model: ctx.model,
    prompt_version: ctx.prompt_version,
    raw_output: text,
    parsed_count: found.size,
    ok,
    error: problems.join('; ').slice(0, 2000),
    duration_ms: Math.max(0, now.getTime() - Number(ctx.startedAt || now.getTime())),
    answered_at: iso,
    ...values,
  },
}];

// After every participant: refresh the run's lock so a long batch is never mistaken for a dead one.
// Output: the update body for the runs table (Touch lock ignores `id` and uses it as the row id).
const run = $('Pick run').first().json.run;
const iso = new Date().toISOString().replace(/\.\d{3}Z$/, '+00:00');
return [{ json: { id: run.id, locked_at: iso, locked_by: $execution.id } }];

// After the batch: recount from the re-read agent_turns and produce the runs-table update body.
// Input: the re-read runs rows (so a status change made during the batch, e.g. paused, is respected).
// The run is done when every participant with a persona has a turn (ok or failed); otherwise it stays
// running and the schedule trigger picks it up again. The lock is released only if this execution
// still owns it; another execution's lock is left untouched.
const run = $('Pick run').first().json.run;
const participants = $('Read: participants').all().map((i) => i.json).filter((p) => p && p.persona);
const turns = $('Read: agent_turns (recount)').all().map((i) => i.json).filter((t) => t && t.run_id === run.run_id);
const current = $input.all().map((i) => i.json).find((r) => r && r.id === run.id) || run;

const latest = new Map();
for (const t of turns) {
  const pid = String(t.participant_id);
  const prev = latest.get(pid);
  if (!prev || String(t.answered_at || '') >= String(prev.answered_at || '')) latest.set(pid, t);
}
const done = [...latest.values()].filter((t) => t.ok === true).length;
const failed = latest.size - done;
const remaining = participants.filter((p) => !latest.has(String(p.participant_id))).length;
const iso = new Date().toISOString().replace(/\.\d{3}Z$/, '+00:00');

let status = remaining === 0 ? 'done' : 'running';
if (current.status === 'paused') status = 'paused';

const body = {
  id: run.id,
  status,
  participants_total: participants.length,
  participants_done: done,
  participants_failed: failed,
  last_batch_at: iso,
  finished_at: status === 'done' ? iso : null,
};
if (!current.locked_by || current.locked_by === $execution.id) {
  body.locked_at = null;
  body.locked_by = '';
}
return [{ json: body }];
